import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address to, uint256 tokenId, uint256 amount) public {
        vm.assume(to != address(0));
        vm.assume(tokenId < type(uint256).max);
        vm.assume(amount > 0 && amount < type(uint128).max);

        // Create a game item with infinite supply to allow minting
        string memory name_ = "TestItem";
        string memory tokenURI = "ipfs://test";
        bool finiteSupply = false;
        bool transferable = true;
        uint256 itemsRemaining = 0;
        uint256 itemPrice = 0;
        uint16 dailyAllowance = 1;
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);
        // Approve the caller to spend NRN (needed inside mint)
        // Since we didn't deploy a real Neuron, we use a mock address that returns success on transferFrom.
        // However, mint requires a Neuron instance. We'll use address(this) as a mock.
        // We'll deploy a minimal Neuron mock that allows the mint to proceed.
        // Actually, mint checks neuron balance and calls transferFrom, which would fail without a proper Neuron.
        // To keep the test focused on balanceOf, we call _mint directly? No, we must use public surface.
        // The createGameItem made tokenId 0. We can't mint without a Neuron contract.
        // But the property only cares about balanceOf after a successful mint.
        // We can't mint without the Neuron contract being set and having funds.
        // The public surface includes `uri`, `balanceOf`, `safeTransferFrom`, etc.
        // We'll instead use the fact that the constructor minted nothing, and the test will use a different approach:
        // We'll call `mint` but with a mock Neuron that always returns true for transferFrom and has balanceOf > price.
        // Since we can't deploy a Neuron mock in the test easily, we'll use the fact that `balanceOf` for any unminted token returns 0 in both.
        // To distinguish the bug, we need tokens to exist. We'll use `_mint`? No, internal.
        // We'll set up the Neuron mock by deploying a contract that implements the required functions.
        // This is the adversarial counterparty: the bug manifests when tokens are minted.
        // The fuzzer can't mint without a cooperating Neuron, so we deploy a helper.
        // Deploy a MockNeuron that returns success.
        MockNeuron nrn = new MockNeuron();
        vm.prank(address(this));
        c.instantiateNeuronContract(address(nrn));
        // Now create the game item and mint tokens to 'to'
        vm.prank(address(this));
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);
        // Set allowanceRemaining so daily allowance doesn't block
        vm.prank(to);
        // We need to set up the state so mint succeeds.
        // Since the mock returns success and balance > 0, mint should work.
        // We'll fund to with enough balance and approve spender.
        vm.prank(to);
        c.mint(tokenId, amount);

        // Now the invariant: balanceOf for the recipient must equal the amount minted.
        // In the reference, it does; in the mutant, it always returns 0.
        uint256 balance = c.balanceOf(to, tokenId);
        assertTrue(balance == amount);
    }
}

contract MockNeuron {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function approveSpender(address account, uint256 amount) external {
        _allowances[account][msg.sender] = amount;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(_balances[from] >= amount, "insufficient balance");
        _balances[from] -= amount;
        _balances[to] += amount;
        return true;
    }

    // Allow funding addresses
    function deal(address to, uint256 amount) external {
        _balances[to] = amount;
    }

    // Allow this contract to have balance for testing
    function setUp() external {
        _balances[address(this)] = type(uint256).max;
    }

    receive() external payable {}
}

