pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this), address(this));
        // Make the test contract an admin so it can create game items and mint
        c.adjustAdminAccess(address(this), true);
    }

    function testFuzz_property(uint256 tokenIdSeed, uint256 quantity) public {
        // bound quantity to avoid excessive supply issues, but keep it wide
        quantity = bound(quantity, 1, 1000);
        // use tokenIdSeed to generate a non-zero account via an address derivation
        // ensure account != address(0)
        address holder = address(uint160(uint256(keccak256(abi.encode(tokenIdSeed)))));
        vm.assume(holder != address(0));

        // create a game item with transferable = true, finite supply = false,
        // high itemsRemaining and dailyAllowance = type(uint16).max so minting is not restricted.
        c.createGameItem("Test", "", false, true, 1000000, 1, type(uint16).max);

        // We need a Neuron instance for the mint to succeed because mint calls _neuronInstance.
        // Deploy a minimal mock Neuron that returns a large balance and allows transfers.
        MockNeuron mockNrn = new MockNeuron();
        // Initialize c's Neuron address; we are owner (setUp uses address(this) as owner).
        c.instantiateNeuronContract(address(mockNrn));

        // Fund holder with mock NRN so balance check passes
        mockNrn.setBalanceOf(holder, type(uint256).max);

        uint256 tokenId = 0; // first created item has id 0

        // Prank as holder and mint tokens to holder
        vm.startPrank(holder);
        c.mint(tokenId, quantity);
        vm.stopPrank();

        // After minting, the holder's balance should be exactly the quantity minted.
        uint256 balance = c.balanceOf(holder, tokenId);

        // The general rule: for an account that had a positive quantity minted,
        // its balanceOf must equal that quantity (which is > 0).
        // The mutant returns 0, so this assertion fails for any quantity > 0.
        assertTrue(balance == quantity);
    }
}

contract MockNeuron {
    mapping(address => uint256) private _balances;

    function setBalanceOf(address account, uint256 amount) external {
        _balances[account] = amount;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function approveSpender(address, uint256) external pure {}

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        _balances[from] -= amount;
        _balances[to] += amount;
        return true;
    }
}

