        c.createGameItem("Item1", "uri1", false, true, 100, 0, 10);
    }

    function testFuzz_property(address account, uint256 id) public {
        // Ensure account is not address(0) because balanceOf for address(0) will revert
        vm.assume(account != address(0));
        // Restrict to existing token IDs so balanceOf does not revert on valid tokens
        vm.assume(id < c.uniqueTokensOutstanding());

        uint256 balanceId = c.balanceOf(account, id);
        uint256 balanceIdPlus1 = c.balanceOf(account, id + 1);

        // The reference C always returns balance of id, which equals balanceId.
        // The mutant always returns balance of id+1, which equals balanceIdPlus1.
        // Therefore, for the reference, balanceOf(account, id) == balanceId is always true.
        // For the mutant, this assertion fails whenever balanceId != balanceIdPlus1.
        assertTrue(c.balanceOf(account, id) == balanceId);
    }
}

